const body = $input.first().json.body;

const ruleSetId     = body.ruleSetId     ?? 'N/A';
const ruleSetName   = body.ruleSetName   ?? 'N/A';
const tenantName    = body.tenantName    ?? 'N/A';
const status        = body.status        ?? 'ACTIVE';
const version       = body.version       ?? '1';
const strategy      = body.strategy      ?? 'N/A';
const activatedBy   = body.activatedBy   ?? 'Système';
const activatedAt   = body.activatedAt   ?? new Date().toISOString();
const recipientsCsv = body.tenantMemberEmailsCsv ?? '';
const recipientList = (body.tenantMemberEmails ?? []).filter(e => e && e.length > 0);

const formatDate = (iso) => {
  try {
    return new Date(iso).toLocaleString('fr-FR', { timeZone: 'Africa/Tunis' });
  } catch { return iso; }
};

const strategyLabel = {
  FIRST_MATCH: 'Premier match',
  ALL_MATCH:   'Tous les matches',
  WEIGHTED:    'Pondéré',
  PRIORITY:    'Priorité'
}[strategy] ?? strategy;

const subject = `[RaaS] RuleSet « ${ruleSetName} » activé — ${tenantName}`;

const htmlBody = `<!DOCTYPE html>
<html lang="fr">
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: Arial, sans-serif; background: #f5f5f5; margin: 0; padding: 20px; }
    .card { background: #ffffff; border-radius: 8px; max-width: 600px;
            margin: 0 auto; padding: 32px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
    .badge { display: inline-block; background: #16a34a; color: #fff;
             font-size: 12px; font-weight: 700; padding: 3px 10px;
             border-radius: 999px; letter-spacing: .5px; }
    h1 { color: #1a1a2e; font-size: 20px; margin: 16px 0 4px; }
    .subtitle { color: #6b7280; font-size: 14px; margin-bottom: 24px; }
    table { width: 100%; border-collapse: collapse; font-size: 14px; }
    td { padding: 10px 12px; border-bottom: 1px solid #e5e7eb; }
    td:first-child { color: #6b7280; width: 40%; }
    td:last-child { color: #111827; font-weight: 600; }
    .footer { margin-top: 28px; font-size: 12px; color: #9ca3af; text-align: center; }
    .cta { display: block; margin: 24px auto 0; padding: 12px 28px;
           background: #1a1a2e; color: #fff; text-decoration: none;
           border-radius: 6px; font-size: 14px; font-weight: 600;
           text-align: center; max-width: 200px; }
  </style>
</head>
<body>
  <div class="card">
    <span class="badge">ACTIVÉ</span>
    <h1>Un nouveau RuleSet est actif</h1>
    <p class="subtitle">Ce RuleSet a été activé dans votre espace tenant et est désormais opérationnel.</p>
    <table>
      <tr><td>Nom du RuleSet</td><td>${ruleSetName}</td></tr>
      <tr><td>Identifiant</td><td>#${ruleSetId}</td></tr>
      <tr><td>Tenant</td><td>${tenantName}</td></tr>
      <tr><td>Version</td><td>v${version}</td></tr>
      <tr><td>Stratégie</td><td>${strategyLabel}</td></tr>
      <tr><td>Statut</td><td>${status}</td></tr>
      <tr><td>Activé par</td><td>${activatedBy}</td></tr>
      <tr><td>Date d'activation</td><td>${formatDate(activatedAt)}</td></tr>
    </table>
    <a class="cta" href="http://localhost:4200/rulesets/${ruleSetId}">Voir le RuleSet</a>
    <p class="footer">Notification automatique — RaaS (Rule as a Service) · ${tenantName}</p>
  </div>
</body>
</html>`;

const textBody = `RuleSet activé : ${ruleSetName}\nTenant : ${tenantName}\nVersion : v${version}\nStratégie : ${strategyLabel}\nActivé par : ${activatedBy}\nDate : ${formatDate(activatedAt)}\n\nConnectez-vous à http://localhost:4200/rulesets/${ruleSetId} pour le consulter.`;

return [{
  json: {
    subject,
    htmlBody,
    textBody,
    recipientsCsv,
    recipientList,
    ruleSetId,
    ruleSetName,
    tenantName,
    activatedBy,
    activatedAt: formatDate(activatedAt)
  }
}];

const data = $('Construire le contenu email').first().json;
console.log(`[RuleSet Notifier] Aucun destinataire pour RuleSet #${data.ruleSetId} (${data.ruleSetName}) — activation enregistrée sans notification email.`);
return [{ json: { skipped: true, reason: 'no_recipients', ruleSetId: data.ruleSetId } }];
